/** Shape of serialized backend errors (`AppError`). */
export interface AppError {
  code:
    | "invalidArgument"
    | "busy"
    | "notRunning"
    | "thermalUnavailable"
    | "limitExceeded"
    | "unsupported"
    | "noSession"
    | "io"
    | "csv"
    | "internal";
  message: string;
}

export function isAppError(e: unknown): e is AppError {
  return typeof e === "object" && e !== null && "code" in e && "message" in e;
}
